// ===== EDIT THESE FOR YOUR LAN =====
const PMS_BASE = 'http://192.168.1.216:8010'; // PC running PMS (uvicorn :8010)
const DEVICE_NAME = 'Press Machine 1';        // must match machines.name in PMS
const DEVICE_UUID = '871fdce1-b1d4-4d8f-ae69-5c173c622c00';
const MACHINE_ID = 7; // machine_id=7; set null to match by name/uuid
// ====================================

msg.pmsBase = String(PMS_BASE).replace(/\/$/, '');
msg.deviceName = DEVICE_NAME;
msg.deviceUuid = DEVICE_UUID;
if (MACHINE_ID !== null && MACHINE_ID !== undefined) msg.machineId = MACHINE_ID;
return msg;

// Forward LIVE SIE/EdgeX readings to PMS (no simulation).
// Keep raw Modbus integers — PMS scales them:
//   Pressed Pos / Live position ×0.001 → mm
//   Pressed Force / Live force ×0.1 → kgf

const src = msg.payload || {};
const incoming = Array.isArray(src.readings) ? src.readings : [];
if (!incoming.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no readings' });
    return null;
}

const NAME_MAP = {
    'live position': 'Live position',
    'live force': 'Live force',
    'live velocity': 'Live Velocity',
    'status': 'status:Int16',
    'status*1': 'status:Int16',
    'live mode': 'Live Mode',
    'total steps': 'Total Steps',
    'live step': 'Live Step',
    'recipe number': 'Recipe number',
    'total amount': 'Total amount',
    'pass amount': 'Pass amount',
    'ng amount': 'NG amount',
    'standby time': 'Standby time',
    'pressing time': 'Pressing time',
    'production time': 'Production time',
    'alarm code': 'Alarm Code',
    'pressing result': 'Pressing result',
    'pressed position (step 1)': 'Pressed position (Step 1)',
    'pressed position (step 2)': 'Pressed position (Step 2)',
    'pressed position (step 3)': 'Pressed position (Step 3)',
    'pressed pos1': 'Pressed position (Step 1)',
    'pressed pos2': 'Pressed position (Step 2)',
    'pressed pos3': 'Pressed position (Step 3)',
    'pressed pos4': 'Pressed position (Step 4)',
    'pressed pos5': 'Pressed position (Step 5)',
    'pressed pos': 'Pressed Pos',
    'pressed force': 'Pressed Force',
    'pressed force1': 'Pressed Force',
    'device type': 'device type:String',
    'device_type': 'device type:String'
};

function stripType(name) {
    let s = String(name || '').trim();
    for (const sep of [';', ':']) {
        if (s.indexOf(sep) >= 0) {
            s = s.split(sep, 1)[0].trim();
            break;
        }
    }
    return s;
}

function canonicalName(rawName) {
    const base = stripType(rawName).toLowerCase().replace(/\s+/g, ' ');
    return NAME_MAP[base] || stripType(rawName);
}

const origin = Number(src.origin) || Date.now();
const byName = {};
let statusRaw = null;
let livePosRaw = null;
let passN = null;
let ngN = null;
let totalN = null;

for (const r of incoming) {
    if (!r || r.name == null) continue;
    const name = canonicalName(r.name);
    let value = r.value;
    if (value === undefined || value === null) value = '';
    value = String(value);

    const num = Number(value);
    if (name === 'Total amount') {
        if (!isNaN(num) && num >= 0) totalN = num;
        else continue;
    }
    if (name === 'Pass amount' && !isNaN(num)) passN = num;
    if (name === 'NG amount' && !isNaN(num)) ngN = num;

    byName[name] = {
        name: name,
        value: value,
        origin: Number(r.origin) || origin
    };

    if (name === 'status:Int16' || /^status$/i.test(stripType(r.name))) {
        statusRaw = value;
    }
    if (name === 'Live position') {
        livePosRaw = value;
    }
}

if (totalN == null && passN != null && ngN != null) {
    totalN = passN + ngN;
    byName['Total amount'] = {
        name: 'Total amount',
        value: String(totalN),
        origin: origin
    };
}

if (statusRaw != null && !byName['Status*1']) {
    byName['Status*1'] = { name: 'Status*1', value: String(statusRaw), origin: origin };
}
if (!byName['device type:String']) {
    byName['device type:String'] = {
        name: 'device type:String',
        value: 'Press',
        origin: origin
    };
}

const readings = Object.keys(byName).map(k => byName[k]);

const needReset = !flow.get('liveLogResetDone');
if (needReset) flow.set('pendingResetLog', true);

const body = {
    id: src.id || ('live-' + origin),
    syncBy: src.syncBy || 'MODBUS',
    deviceName: msg.deviceName,
    device: msg.deviceUuid || src.device,
    origin: origin,
    readings: readings,
    replaceReadings: true
};
if (needReset) body.resetLog = true;
if (msg.machineId) body.machine_id = msg.machineId;

msg.payload = body;
msg.headers = { 'Content-Type': 'application/json' };
msg.url = msg.pmsBase + '/api/machines/telemetry';
msg.method = 'POST';
msg.status = statusRaw != null ? Number(statusRaw) : undefined;
msg.livePositionRaw = livePosRaw;
msg.livePositionMm = livePosRaw != null && livePosRaw !== ''
    ? (Number(livePosRaw) * 0.001)
    : undefined;

const posTxt = msg.livePositionMm != null && !isNaN(msg.livePositionMm)
    ? (' pos=' + msg.livePositionMm.toFixed(3) + 'mm')
    : '';
const totTxt = totalN != null ? (' tot=' + totalN) : '';
node.status({
    fill: 'green',
    shape: 'dot',
    text: 'status=' + (statusRaw != null ? statusRaw : '?') + posTxt + totTxt +
        (needReset ? ' resetLog' : '') + ' → PMS'
});
return msg;

const code = msg.statusCode;
const ok = typeof code === 'number' && code >= 200 && code < 300;
if (ok && flow.get('pendingResetLog')) {
    flow.set('liveLogResetDone', true);
    flow.set('pendingResetLog', false);
    node.status({ fill: 'green', shape: 'dot', text: 'log reset done' });
}
return null;

flow.set('liveLogResetDone', false);
node.status({ fill: 'yellow', shape: 'ring', text: 'next post will resetLog' });
node.warn('Next live telemetry POST will send resetLog=true (clears alarm/history residue).');
return null;
